tile.clickEventHandler:
ESS.network.sendRequest(`/api/functions/IsDepartmentManagerWithSubtitute`)
.then(function (isDepartmentManager) {
  if (isDepartmentManager) {
    ESS.actions.facilityActions.runFacility({ id: 'ecf47cff-7040-470b-8efb-0c4230d86622'});
  }
  else {
    ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.FACILITIES_RECALLVACATIONEMPLOYEE_WARNING'), ESS.L('@HRPROVACATIONS.FACILITIES_RECALLVACATIONEMPLOYEE_ISDEPARTMENTMANAGER_ERROR'));
  }
})
.catch(function (error) {
          ESS.toasts.showToast(error.message, 'danger', false);
});
